/// The generated template of `enc`, if there is one.
pub(crate) fn template(enc: Encoding) -> Option<GenFn> {
    Some(match enc {
        Encoding::Bc1f => Bc1f,
        Encoding::Bc1t => Bc1t,
        Encoding::Bc1fl => Bc1fl,
        Encoding::Bc1tl => Bc1tl,
        Encoding::J => J,
        Encoding::Jal => Jal,
        Encoding::Jr => Jr,
        Encoding::Jalr => Jalr,
        Encoding::Beq => Beq,
        Encoding::Beql => Beql,
        Encoding::Bne => Bne,
        Encoding::Bnel => Bnel,
        Encoding::Bltz => Bltz,
        Encoding::Bltzal => Bltzal,
        Encoding::Bltzl => Bltzl,
        Encoding::Bltzall => Bltzall,
        Encoding::Bgez => Bgez,
        Encoding::Bgezal => Bgezal,
        Encoding::Bgezl => Bgezl,
        Encoding::Bgezall => Bgezall,
        Encoding::Bgtz => Bgtz,
        Encoding::Bgtzl => Bgtzl,
        Encoding::Blez => Blez,
        Encoding::Blezl => Blezl,
        _ => return None,
    })
}
